def matched_seed(base_seed, target_id, restart):
    key = (int(base_seed), str(target_id), int(restart))
    try:
        return MATCHED_SEEDS[key]
    except KeyError as error:
        raise ValueError(f"Undeclared RINENG start: {key!r}") from error


def bootstrap_stream(master_seed, identity):
    key = (int(master_seed), tuple(str(value) for value in identity))
    try:
        return BOOTSTRAP_STREAMS[key]
    except KeyError as error:
        raise ValueError(f"Undeclared RINENG bootstrap stream: {key!r}") from error
